chk("approval all: a new item waits; an item that was already live stays live; one already waiting stays waiting", A.placeOf(st("all"), base, was(false, false)) === "pending" && A.placeOf(st("all"), base, was(true, false)) === "live" && A.placeOf(st("off"), base, was(false, true)) === "pending");
