  chk("topics: a new topic gets an upper-case key and its keywords are cleaned", st.settings.topics.length === 1 && st.settings.topics[0].k === "HOUSING VOUCHERS" && JSON.stringify(st.settings.topics[0].words) === '["section 8","housing voucher","rent relief"]', JSON.stringify(st.settings.topics));
  chk("topics: the summary names the new topic", op(A.emptyState(), "topics", { list: [{ label: "Climate" }] }).summary === "Added the topic “Climate”");
