  chk("topics: two of the owner's topics cannot share a name", thr(() => op(st, "topics", { list: [{ label: "Zed" }, { label: "ZED" }] }), /already a topic/));
  chk("topics: a name without letters or numbers, an empty name and a non-list are refused", thr(() => op(st, "topics", { list: [{ label: "!!!" }] }), /letters or numbers/) && thr(() => op(st, "topics", { list: [{ label: "  " }] }), /needs a name/) && thr(() => op(st, "topics", { list: "x" }), /could not be read/));
  chk("topics: at most 30, and at most 40 keywords each", thr(() => op(st, "topics", { list: Array.from({ length: 31 }, (_, i) => ({ label: "T" + i })) }), /at most 30/) && thr(() => op(st, "topics", { list: [{ label: "Many", words: Array.from({ length: 41 }, (_, i) => "word" + i) }] }), /40 keywords/));
  chk("topics: sending the same list again changes nothing and is refused", thr(() => op(st, "topics", { list: [{ k: "HOUSING VOUCHERS", label: "Housing vouchers", words: ["section 8", "housing voucher", "rent relief"] }] }), /Nothing to change/));
